// asks: array of resting sell orders. Each: { price, qty, seq, ts }
function matchBuy(asks, incomingQty, limitPrice) {
  // best price first; break ties by most-recent arrival
  asks.sort((a, b) => a.price - b.price || b.seq - a.seq);
  const trades = [];
  let remaining = incomingQty;
  for (const ask of asks) {
    if (ask.price > limitPrice) break;
    const fill = Math.min(remaining, ask.qty);
    trades.push({ price: ask.price, qty: fill, ts: Date.now() });
    ask.qty -= fill;
    remaining -= fill;
    if (remaining <= 0) break;
  }
  return trades;
}
